function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PREDICTION_MODELS_TABLE = 10; // 需要予測結果テーブルをモデル管理として使用

  // 再描画関数の定義
  function renderModelList(models) {
    const tbody = container.querySelector("#model-list");
    tbody.innerHTML = models.map(model => `
      <tr data-id="${model.id}">
        <td>${model.modelName || ""}</td>
        <td>${model.storeName || ""}</td>
        <td>${model.predictionPeriod || ""}日</td>
        <td>${model.algorithm || ""}</td>
        <td>${model.accuracyTarget || ""}%</td>
        <td>${model.createdAt ? new Date(model.createdAt).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${model.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${model.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧の読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector("#target-store");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(store => `<option value="${store.id}">${store.storeName}</option>`).join("");
    }
  }

  // 初期データの読み込み
  async function loadInitialData() {
    await loadStores();
    const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
    if (models) {
      renderModelList(models);
    }
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const modelName = container.querySelector("#model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    const targetStore = container.querySelector("#target-store").value;
    if (!targetStore) {
      errors.push("対象店舗を選択してください");
    }

    const categories = container.querySelectorAll('input[name="category"]:checked');
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    const startDate = container.querySelector("#learning-start-date").value;
    const endDate = container.querySelector("#learning-end-date").value;
    if (!startDate || !endDate) {
      errors.push("学習期間を設定してください");
    } else if (new Date(startDate) > new Date(endDate)) {
      errors.push("開始日は終了日より前の日付を設定してください");
    } else if (new Date(startDate) > new Date() || new Date(endDate) > new Date()) {
      errors.push("学習期間に未来の日付は設定できません");
    }

    const dataSources = container.querySelectorAll('input[name="datasource"]:checked');
    if (dataSources.length === 0) {
      errors.push("データソースを選択してください");
    }

    const algorithm = container.querySelector("#algorithm").value;
    if (!algorithm) {
      errors.push("アルゴリズムを選択してください");
    }

    const accuracyTarget = parseInt(container.querySelector("#accuracy-target").value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push("モデル精度目標値は0-100%の範囲で入力してください");
    }

    // 重み付け設定の合計チェック
    const weightTotal = parseInt(container.querySelector("#weight-total").textContent);
    if (weightTotal !== 100) {
      errors.push("重み付けの合計値は100%である必要があります");
    }

    // 季節性パラメータの数値チェック
    const seasonalStrength = container.querySelector("#seasonal-strength").value;
    const trendStrength = container.querySelector("#trend-strength").value;
    if (isNaN(seasonalStrength) || isNaN(trendStrength)) {
      errors.push("季節性パラメータには数値を入力してください");
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorDiv = container.querySelector("#error-messages");
    if (errors.length > 0) {
      errorDiv.innerHTML = `<ul>${errors.map(err => `<li>${err}</li>`).join("")}</ul>`;
      errorDiv.classList.remove("hidden");
    } else {
      errorDiv.classList.add("hidden");
    }
  }

  // 重み付け合計の更新
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll(".weight-input");
    let total = 0;
    weightInputs.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    container.querySelector("#weight-total").textContent = total;
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector("#learning-rate");
    const display = container.querySelector("#learning-rate-value");
    display.textContent = slider.value;
  }

  // 全選択チェックボックスの処理
  function setupSelectAllCheckboxes() {
    // カテゴリの全選択
    const selectAllCategories = container.querySelector("#select-all-categories");
    const categoryCheckboxes = container.querySelectorAll('input[name="category"]');

    selectAllCategories.addEventListener("change", function() {
      categoryCheckboxes.forEach(cb => cb.checked = this.checked);
    });

    // データソースの全選択
    const selectAllDataSources = container.querySelector("#select-all-datasources");
    const dataSourceCheckboxes = container.querySelectorAll('input[name="datasource"]');

    selectAllDataSources.addEventListener("change", function() {
      dataSourceCheckboxes.forEach(cb => cb.checked = this.checked);
    });
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    container.querySelector("#btn-search").addEventListener("click", async () => {
      const keyword = container.querySelector("#search-input").value.trim();
      const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
      if (models) {
        const filtered = keyword ? 
          models.filter(model => JSON.stringify(model).toLowerCase().includes(keyword.toLowerCase())) : 
          models;
        renderModelList(filtered);
      }
    });

    // 保存ボタン
    container.querySelector("#btn-save").addEventListener("click", async () => {
      const errors = validateForm();
      showErrors(errors);

      if (errors.length > 0) return;

      const formData = {
        modelName: container.querySelector("#model-name").value.trim(),
        storeId: container.querySelector("#target-store").value,
        storeName: container.querySelector("#target-store").selectedOptions[0]?.textContent || "",
        categories: Array.from(container.querySelectorAll('input[name="category"]:checked')).map(cb => cb.value),
        learningStartDate: container.querySelector("#learning-start-date").value,
        learningEndDate: container.querySelector("#learning-end-date").value,
        predictionPeriod: container.querySelector('input[name="prediction-period"]:checked').value,
        dataSources: Array.from(container.querySelectorAll('input[name="datasource"]:checked')).map(cb => cb.value),
        algorithm: container.querySelector("#algorithm").value,
        learningRate: parseFloat(container.querySelector("#learning-rate").value),
        weights: {
          sales: parseInt(container.querySelector('[data-factor="sales"]').value),
          weather: parseInt(container.querySelector('[data-factor="weather"]').value),
          events: parseInt(container.querySelector('[data-factor="events"]').value),
          seasonal: parseInt(container.querySelector('[data-factor="seasonal"]').value)
        },
        seasonalStrength: parseFloat(container.querySelector("#seasonal-strength").value),
        trendStrength: parseFloat(container.querySelector("#trend-strength").value),
        excludeOutliers: container.querySelector("#exclude-outliers").checked,
        accuracyTarget: parseInt(container.querySelector("#accuracy-target").value),
        createdAt: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(PREDICTION_MODELS_TABLE, formData);
      if (saved) {
        alert("モデルが正常に作成されました");
        // フォームリセット
        container.querySelector("#model-name").value = "";
        container.querySelector("#target-store").value = "";
        container.querySelectorAll('input[name="category"]').forEach(cb => cb.checked = false);
        container.querySelector("#select-all-categories").checked = false;
        // モデル一覧を再読み込み
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        if (models) renderModelList(models);
      }
    });

    // テストボタン
    container.querySelector("#btn-test").addEventListener("click", () => {
      window.showScreen("scr-1778591999045"); // モデルテスト機能
    });

    // 戻るボタン
    container.querySelector("#btn-back").addEventListener("click", () => {
      window.showScreen("scr-1778591780173"); // ダッシュボード
    });

    // 重み付け入力の変更監視
    container.querySelectorAll(".weight-input").forEach(input => {
      input.addEventListener("input", updateWeightTotal);
    });

    // 学習率スライダーの変更監視
    container.querySelector("#learning-rate").addEventListener("input", updateLearningRateDisplay);

    // 行レベル操作（編集・削除）
    container.addEventListener("click", async (e) => {
      const editBtn = e.target.closest(".edit-btn");
      const deleteBtn = e.target.closest(".delete-btn");

      if (editBtn) {
        const modelId = editBtn.dataset.id;
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        const model = models?.find(m => m.id === modelId);
        if (model) {
          // フォームに既存データを設定
          container.querySelector("#model-name").value = model.modelName || "";
          container.querySelector("#target-store").value = model.storeId || "";
          if (model.categories) {
            model.categories.forEach(cat => {
              const checkbox = container.querySelector(`input[name="category"][value="${cat}"]`);
              if (checkbox) checkbox.checked = true;
            });
          }
          container.querySelector("#learning-start-date").value = model.learningStartDate || "";
          container.querySelector("#learning-end-date").value = model.learningEndDate || "";
          if (model.predictionPeriod) {
            const radio = container.querySelector(`input[name="prediction-period"][value="${model.predictionPeriod}"]`);
            if (radio) radio.checked = true;
          }
          if (model.dataSources) {
            model.dataSources.forEach(ds => {
              const checkbox = container.querySelector(`input[name="datasource"][value="${ds}"]`);
              if (checkbox) checkbox.checked = true;
            });
          }
          container.querySelector("#algorithm").value = model.algorithm || "";
          container.querySelector("#learning-rate").value = model.learningRate || 0.01;
          updateLearningRateDisplay();
          if (model.weights) {
            container.querySelector('[data-factor="sales"]').value = model.weights.sales || 0;
            container.querySelector('[data-factor="weather"]').value = model.weights.weather || 0;
            container.querySelector('[data-factor="events"]').value = model.weights.events || 0;
            container.querySelector('[data-factor="seasonal"]').value = model.weights.seasonal || 0;
            updateWeightTotal();
          }
          container.querySelector("#seasonal-strength").value = model.seasonalStrength || 1.0;
          container.querySelector("#trend-strength").value = model.trendStrength || 1.0;
          container.querySelector("#exclude-outliers").checked = model.excludeOutliers || false;
          container.querySelector("#accuracy-target").value = model.accuracyTarget || 85;
        }
      }

      if (deleteBtn) {
        if (!confirm("このモデルを削除しますか？")) return;
        const modelId = deleteBtn.dataset.id;
        await window.aivicApi.delete(PREDICTION_MODELS_TABLE, modelId);
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        if (models) renderModelList(models);
      }
    });
  }

  // 初期化
  setupSelectAllCheckboxes();
  setupEventListeners();
  updateLearningRateDisplay();
  updateWeightTotal();
  loadInitialData();
}
